def transform(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    def runs_row(r):
        res=[];c=0
        while c<W:
            if g[r][c]:
                s=c
                while c<W and g[r][c]: c+=1
                res.append((s,g[r][s:c]))
            else: c+=1
        return res
    src=[(r,s,v) for r in (0,H-1) for s,v in runs_row(r) if len(v)>1]
    mk=[]
    for r in range(H):
        if r in (0,H-1): continue
        for c in range(W):
            if g[r][c] and (c==0 or g[r][c-1]==0) and (c==W-1 or g[r][c+1]==0):
                mk.append((r,c,g[r][c])); g[r][c]=0
    for r,c,v in mk:
        for sr,ss,vals in src:
            if v in vals:
                i=vals.index(v); L=len(vals); s=c-i+(1 if (i==L-1 and r+c>=15) else 0)
                for k,x in enumerate(vals):
                    if 0<=s+k<W: g[r][s+k]=x
                break
    return g

